    <script>
        // React-like combobox behavior simulation
        document.querySelectorAll('.combobox-container').forEach(container => {
            const control = container.querySelector('.combobox-control');
            const input = container.querySelector('.combobox-input');
            const menu = container.querySelector('.combobox-menu');
            const options = container.querySelectorAll('.combobox-option');
            const indicator = container.querySelector('.combobox-indicator');

            // Toggle dropdown on click
            control.addEventListener('click', (e) => {
                if (e.target === indicator) {
                    toggleMenu();
                }
            });

            // Open dropdown on focus + ArrowDown
            input.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    openMenu();
                }
            });

            // Filter options on input
            input.addEventListener('input', (e) => {
                const value = e.target.value.toLowerCase();
                openMenu();
                options.forEach(opt => {
                    const text = opt.textContent.toLowerCase();
                    const dataValue = opt.dataset.value.toLowerCase();
                    opt.style.display = (text.includes(value) || dataValue.includes(value)) ? 'block' : 'none';
                });
            });

            // Select option
            options.forEach(opt => {
                opt.addEventListener('click', () => {
                    const value = opt.dataset.value;
                    input.value = opt.textContent;
                    closeMenu();

                    // Handle "Other" option
                    if (value === 'other') {
                        const otherInput = document.getElementById(input.id + '-other');
                        if (otherInput) {
                            otherInput.classList.add('visible');
                            otherInput.focus();
                        }
                    }

                    // Dispatch change event
                    input.dispatchEvent(new Event('change', { bubbles: true }));
                });
            });

            // Click outside to close
            document.addEventListener('click', (e) => {
                if (!container.contains(e.target)) {
                    closeMenu();
                }
            });

            function openMenu() {
                menu.classList.add('open');
                control.setAttribute('aria-expanded', 'true');
            }

            function closeMenu() {
                menu.classList.remove('open');
                control.setAttribute('aria-expanded', 'false');
            }

            function toggleMenu() {
                if (menu.classList.contains('open')) {
                    closeMenu();
                } else {
                    openMenu();
                }
            }
        });
    </script>
